        const HTMLElementCtor = typeof globalThis !== 'undefined' ? globalThis.HTMLElement : null;
        return typeof HTMLElementCtor?.prototype?.showPopover === 'function'
            && typeof HTMLElementCtor?.prototype?.hidePopover === 'function';
