                return createSVG('0 0 24 24', [
                    { type: 'rect', x: 9, y: 9, width: 11, height: 11, rx: 2 },
                    { type: 'path', d: 'M6 15H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v1' }
                ], { strokeWidth: '2', strokeLinecap: 'round', strokeLinejoin: 'round' });
