            group: 'Video Player',
            icon: 'eye',
            pages: [PageTypes.WATCH],
            _styleEl: null,
            _alert: null,
            _alertTimer: null,
            _mountTaskId: 'feature:photosensitiveFlashProtection',
            _settingsHandler: null,
